/**
 * Domain Lookup Utility
 *
 * Resolves custom domains to project information via API lookup.
 * Supports optional CacheRepository injection for testing and distributed caching.
 *
 * @module server/utils/domain-lookup
 */
import { logger as baseLogger } from "../../utils/index.js";
import { injectContext, withSpan } from "../../observability/tracing/otlp-setup.js";
import { LRUCache } from "../../utils/lru-wrapper.js";
import { registerLRUCache } from "../../cache/index.js";
const logger = baseLogger.component("domain-lookup");
/**
 * Thrown when the domain lookup API returns a transient non-404 error (e.g., 500, 503).
 * Callers should distinguish this from a null return (domain genuinely not mapped):
 * a null return means 404/not-found, this error means the lookup service itself failed
 * and the request should be treated as a 502 rather than a 404.
 */
export class DomainLookupApiError extends Error {
    status;
    statusText;
    constructor(status, statusText, domain) {
        super(`Domain lookup API error for "${domain}": ${status} ${statusText}`);
        this.status = status;
        this.statusText = statusText;
        this.name = "DomainLookupApiError";
    }
}
const DOMAIN_CACHE_TTL_MS = 60_000;
const DOMAIN_CACHE_MAX_ENTRIES = 1000;
/** Timeout for domain lookup API calls (10 seconds) */
const DOMAIN_LOOKUP_TIMEOUT_MS = 10_000;
/** TTL in seconds for external cache repository */
const DOMAIN_CACHE_TTL_SECONDS = 60;
const domainCache = new LRUCache({
    maxEntries: DOMAIN_CACHE_MAX_ENTRIES,
    ttlMs: DOMAIN_CACHE_TTL_MS,
});
// Register cache for monitoring
registerLRUCache("domain-lookup-cache", domainCache);
const inFlightRequests = new Map();
/** Injected cache repository for testing or distributed caching */
let injectedCacheRepo = null;
function normalizeDomain(domain) {
    return domain.replace(/:\d+$/, "").toLowerCase();
}
async function getCachedResult(cacheKey, domain) {
    if (injectedCacheRepo) {
        const cached = await injectedCacheRepo.get(cacheKey);
        if (!cached)
            return undefined;
        const result = JSON.parse(cached);
        logger.debug("Repository cache hit", {
            domain,
            projectSlug: result?.project_slug,
        });
        return result;
    }
    const cached = domainCache.get(cacheKey);
    if (!cached)
        return undefined;
    logger.debug("Cache hit", {
        domain,
        projectSlug: cached.result?.project_slug,
    });
    return cached.result;
}
function setCachedResult(cacheKey, result) {
    if (injectedCacheRepo) {
        return injectedCacheRepo.set(cacheKey, JSON.stringify(result), DOMAIN_CACHE_TTL_SECONDS);
    }
    domainCache.set(cacheKey, { result });
}
export function lookupProjectByDomain(domain, config) {
    return withSpan("server.domainLookup.lookup", async () => {
        const cacheKey = normalizeDomain(domain);
        const cached = await getCachedResult(cacheKey, domain);
        if (cached !== undefined)
            return cached;
        const inFlight = inFlightRequests.get(cacheKey);
        if (inFlight) {
            logger.debug("Waiting for in-flight request", { domain });
            return inFlight;
        }
        const requestPromise = fetchDomainLookup(domain, config);
        inFlightRequests.set(cacheKey, requestPromise);
        try {
            const result = await requestPromise;
            await setCachedResult(cacheKey, result);
            return result;
        }
        finally {
            inFlightRequests.delete(cacheKey);
        }
    }, { "domain.lookup.domain": domain });
}
function fetchDomainLookup(domain, config) {
    return withSpan("server.domainLookup.fetch", async () => {
        const domainWithoutPort = domain.replace(/:\d+$/, "");
        const normalizedDomain = domainWithoutPort.toLowerCase();
        const url = `${config.apiBaseUrl}/projects/${encodeURIComponent(domainWithoutPort)}`;
        logger.debug("Fetching from API", { domain, url });
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), DOMAIN_LOOKUP_TIMEOUT_MS);
        try {
            const headers = new Headers({
                Authorization: `Bearer ${config.apiToken}`,
                Accept: "application/json",
            });
            injectContext(headers);
            const response = await fetch(url, {
                headers,
                signal: controller.signal,
            });
            if (response.status === 404) {
                logger.debug("No project found for domain", { domain });
                return null;
            }
            if (!response.ok) {
                logger.error("API error, throwing DomainLookupApiError so callers can return 502", {
                    domain,
                    status: response.status,
                    statusText: response.statusText,
                });
                // Throw instead of returning null: null means "domain not found" (404 to client).
                // A 5xx from the lookup API is a transient outage, not a missing mapping.
                // Callers should catch DomainLookupApiError and respond with 502 instead of 404.
                throw new DomainLookupApiError(response.status, response.statusText, domain);
            }
            const project = (await response.json());
            const matchingEnv = project.environments?.find((env) => env.domains?.some((d) => d.toLowerCase() === normalizedDomain));
            const result = {
                project_id: project.id,
                project_slug: project.slug,
                project_name: project.name,
                environment: matchingEnv ? { id: matchingEnv.id, name: matchingEnv.name } : null,
                release_id: matchingEnv?.active_release_id ?? null,
            };
            logger.debug("Domain lookup result", {
                domain,
                projectSlug: result.project_slug,
                environment: result.environment?.name,
            });
            return result;
        }
        catch (error) {
            const isTimeout = error instanceof Error && error.name === "AbortError";
            logger.error("Failed to lookup domain", {
                domain,
                error: error instanceof Error ? error.message : String(error),
                timeout: isTimeout,
            });
            return null;
        }
        finally {
            clearTimeout(timeoutId);
        }
    }, { "domain.fetch.domain": domain });
}
export function clearDomainCache() {
    domainCache.clear();
    inFlightRequests.clear();
    if (injectedCacheRepo?.clear)
        void injectedCacheRepo.clear();
    logger.debug("Cache cleared");
}
/**
 * Inject a CacheRepository for testing or distributed caching.
 * Call with null to restore default Map-based caching.
 *
 * @example
 * ```typescript
 * import { MockCacheRepository, createMockRepositoryContext } from "#veryfront/repositories/testing";
 *
 * const mockCache = new MockCacheRepository({ context: createMockRepositoryContext() });
 * __injectCacheForTests(mockCache);
 *
 * // Run tests...
 *
 * __injectCacheForTests(null); // Restore default
 * ```
 */
export function __injectCacheForTests(cacheRepo) {
    injectedCacheRepo = cacheRepo;
}
export function getEnvironmentType(result) {
    const envName = result?.environment?.name.toLowerCase();
    if (!envName)
        return undefined;
    if (envName.includes("production") || envName === "prod")
        return "production";
    if (envName.includes("preview") || envName.includes("staging") || envName.includes("development")) {
        return "preview";
    }
    // Unknown environment names default to "preview" (safe: does not expose released/production
    // content to the public). Defaulting to "production" for an unknown env name would risk
    // serving production content to users on environments that are not intentionally public.
    return "preview";
}
